query CandidateProducts($query: String!) {
  products(first: 10, query: $query) {
    nodes {
      id
      title
      handle
      status
      totalInventory
      variants(first: 10) {
        nodes {
          id
          title
          inventoryQuantity
          inventoryItem {
            unitCost {
              amount
              currencyCode
            }
          }
        }
      }
      collections(first: 20) {
        nodes {
          id
          title
          handle
        }
      }
    }
  }
}

